def color_counts(grid, exclude=()):
    """Multiset of cell colors in the grid, optionally excluding some colors."""
    return Counter(v for row in grid for v in row if v not in exclude)

def dominant_color(grid, exclude=()):
    """The most frequent color in the grid, optionally ignoring excluded colors (e.g. the background 0)."""
    return color_counts(grid, exclude).most_common(1)[0][0]

def shape_by_dominant(grid, shapes, exclude=()):
    """Return the fixed shape looked up by the grid's dominant color (a color-to-shape mapping rule)."""
    return [row[:] for row in shapes[dominant_color(grid, exclude)]]
